use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_ast::{self as ast, Expr};
use ruff_python_trivia::{is_python_whitespace, Cursor, SimpleTokenKind, SimpleTokenizer};
use ruff_text_size::{Ranged, TextRange, TextSize};

use crate::checkers::ast::Checker;
use crate::Locator;

/// ## What it does
/// Checks for unnecessary dictionary unpacking operators (`**`).
///
/// ## Why is this bad?
/// Unpacking a dictionary into another dictionary is redundant. The unpacking
/// operator can be removed, making the code more readable.
///
/// ## Example
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, **{"C": 3}}
/// ```
///
/// Use instead:
/// ```python
/// foo = {"A": 1, "B": 2}
/// bar = {**foo, "C": 3}
/// ```
///
/// ## References
/// - [Python documentation: Dictionary displays](https://docs.python.org/3/reference/expressions.html#dictionary-displays)
#[derive(ViolationMetadata)]
pub(crate) struct UnnecessarySpread;

impl Violation for UnnecessarySpread {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Unnecessary spread `**`".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove unnecessary dict".to_string())
    }
}

/// PIE800
pub(crate) fn unnecessary_spread(checker: &mut Checker, dict: &ast::ExprDict) {
    // The first "end" is the start of the dictionary, immediately following the open bracket.
    let mut prev_end = dict.start() + TextSize::from(1);
    for ast::DictItem { key, value } in dict {
        if key.is_none() {
            // We only care about when the key is None which indicates a spread `**`
            // inside a dict.
            if let Expr::Dict(inner) = value {
                let mut diagnostic = Diagnostic::new(UnnecessarySpread, value.range());
                if let Some(fix) = unnecessary_spread_fix(inner, prev_end, checker.locator()) {
                    diagnostic.set_fix(fix);
                }
                checker.diagnostics.push(diagnostic);
            }
        }
        prev_end = value.end();
    }
}

/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    let source = locator.contents();
    if locator.is_empty() {
        return None;
    }

    let remaining = locator.after(prev_end);
    if !remaining.is_empty() {
        let dict_start = dict.start();
        let dict_end = dict.end();
        let open_end = dict_start + TextSize::from(1);

        // Locate the last unpacked value so the trailing closer can be found.
        let mut last_value_end: Option<TextSize> = None;
        for item in dict {
            let value = &item.value;
            let value_range = value.range();
            let value_end = value_range.end();
            last_value_end = Some(value_end);
        }

        // Inline the simple-token scanner used to find the preceding `**`.
        let mut scan_offset = prev_end;
        let mut cursor = Cursor::new(remaining);
        let mut doublestar_range: Option<TextRange> = None;
        loop {
            cursor.start_token();
            let Some(first) = cursor.bump() else {
                break;
            };
            let kind = match first {
                c if is_python_whitespace(c) => {
                    cursor.eat_while(is_python_whitespace);
                    SimpleTokenKind::Whitespace
                }
                '\n' => SimpleTokenKind::Newline,
                '\r' => {
                    cursor.eat_char('\n');
                    SimpleTokenKind::Newline
                }
                '#' => {
                    cursor.eat_while(|c| c != '\n' && c != '\r');
                    SimpleTokenKind::Comment
                }
                '\\' => SimpleTokenKind::Continuation,
                '*' => {
                    if cursor.eat_char('*') {
                        if cursor.eat_char('=') {
                            SimpleTokenKind::DoubleStarEqual
                        } else {
                            SimpleTokenKind::DoubleStar
                        }
                    } else if cursor.eat_char('=') {
                        SimpleTokenKind::StarEqual
                    } else {
                        SimpleTokenKind::Star
                    }
                }
                '{' => SimpleTokenKind::LBrace,
                '}' => SimpleTokenKind::RBrace,
                '(' => SimpleTokenKind::LParen,
                ')' => SimpleTokenKind::RParen,
                ',' => SimpleTokenKind::Comma,
                c if c.is_alphabetic() || c == '_' => {
                    cursor.eat_while(|ch| ch.is_alphanumeric() || ch == '_');
                    SimpleTokenKind::Name
                }
                _ => SimpleTokenKind::Other,
            };
            let token_len = cursor.token_len();
            let range = TextRange::at(scan_offset, token_len);
            scan_offset += token_len;
            let token_text = locator.slice(range);
            if kind == SimpleTokenKind::DoubleStar && token_text == "**" {
                doublestar_range = Some(range);
                break;
            }
        }

        if let Some(doublestar_range) = doublestar_range {
            if let Some(last_end) = last_value_end {
                // Ex) `**{a: 1, b: 2}`
                let mut edits = Vec::new();
                let closer_source = locator.after(last_end);
                if !closer_source.is_empty() {
                    for tok in SimpleTokenizer::starts_at(last_end, source) {
                        match tok.kind() {
                            SimpleTokenKind::Whitespace
                            | SimpleTokenKind::Newline
                            | SimpleTokenKind::Comment
                            | SimpleTokenKind::Continuation => continue,
                            SimpleTokenKind::Comma => {
                                let comma_range = tok.range();
                                let comma_edit = Edit::range_deletion(comma_range);
                                edits.push(comma_edit);
                            }
                            SimpleTokenKind::RBrace => {
                                let brace_range = tok.range();
                                let brace_edit = Edit::range_deletion(brace_range);
                                edits.push(brace_edit);
                                break;
                            }
                            SimpleTokenKind::RParen | SimpleTokenKind::LParen => continue,
                            _ => {}
                        }
                    }
                }
                edits.sort_by_key(|edit| (edit.start(), edit.end()));
                let leading_start = doublestar_range.start();
                let leading_end = open_end;
                let leading_edit = Edit::deletion(leading_start, leading_end);
                return Some(Fix::safe_edits(
                    // Delete the first `**{`
                    leading_edit,
                    // Delete the trailing `}`
                    edits,
                ));
            }

            // Ex) `**{}`
            let empty_start = doublestar_range.start();
            let empty_end = dict_end;
            let empty_edit = Edit::deletion(empty_start, empty_end);
            return Some(Fix::safe_edit(empty_edit));
        }
    }
    None
}

